package fleet

import (
	"list"
	"math"
)

#Region: "us-east" | "us-west" | "eu-central" | "ap-south"

#Tier: "small" | "medium" | "large"

#tierSpecs: {
	small:  {cpu: 1, memoryMB:  512, replicas: 1}
	medium: {cpu: 2, memoryMB: 2048, replicas: 3}
	large:  {cpu: 4, memoryMB: 8192, replicas: 5}
}

#Service: {
	id:       int
	name:     string
	region:   #Region
	tier:     #Tier
	spec:     #tierSpecs[tier]
	enabled:  bool
	replicas: int & >=1 & <=10
	replicas: spec.replicas
	labels: {
		team:  "team-\(math.Mod(id, 8))"
		env:   ["dev", "staging", "prod"][int & math.Trunc(math.Mod(id, 3))]
		owner: "owner-\(math.Mod(id, 20))"
	}
	ports: [for p in list.Range(0, 3, 1) {8000 + (int & math.Trunc(math.Mod(id, 1000)))*3 + p}]
}

_regionsList: ["us-east", "us-west", "eu-central", "ap-south"]
_tiersList: ["small", "medium", "large"]

services: [
	for i in list.Range(0, 1500, 1) {
		#Service & {
			id:      i
			name:    "svc-\(i)"
			region:  _regionsList[int & math.Trunc(math.Mod(i, len(_regionsList)))]
			tier:    _tiersList[int & math.Trunc(math.Mod(i, len(_tiersList)))]
			enabled: math.Mod(i, 5) != 0
		}
	},
]

totalReplicas: {
	for s in services {
		"\(s.id)": s.replicas
	}
}

summary: {
	count: len(services)
	byRegion: {
		for r in _regionsList {
			"\(r)": len([for s in services if s.region == r {s}])
		}
	}
}

